export const MASTER_PLAN_HTML = {
  "overview": "<div class=\"section-header\">\n          <div class=\"section-icon-badge\">\ud83d\udca1</div>\n          <h2 class=\"section-title\">The Most Important Insight &amp; Central Crisis</h2>\n        </div>\n\n        <div class=\"callout danger\">\n          <div class=\"callout-icon\">\ud83d\udea8</div>\n          <div class=\"callout-body\">\n            <strong>Read the Rubric, Not Just the Problem Title:</strong>\n            40% of all evaluation marks are allocated purely to privacy (PII Detection Recall &amp; Precision 20% + Redaction Precision 20%). 20% is Client-side Resource Utilization. Only 15% is End-to-End Latency. ISRO is <strong>not</strong> primarily grading a flashy browser agent; they are grading a <strong>Zero-Trust Visual Sanitization Layer</strong> that enables a browser agent safely.\n          </div>\n        </div>\n\n        <div class=\"callout warn\">\n          <div class=\"callout-icon\">\u2696</div>\n          <div class=\"callout-body\">\n            <strong>The Architectural Mandate:</strong>\n            The problem statement states explicitly: <em>\"it shall sanitize the sensitive/PII data\u2026 before any network request is made.\"</em> This single constraint instantly disqualifies every existing commercial browser agent on earth. Your local vision model is not an optional accessory \u2014 it is the legal and technical foundation of the entire submission.\n          </div>\n        </div>\n\n        <!-- VISUAL COMPARISON: WRONG VS CORRECT -->\n        <div class=\"visual-comparison-grid\">\n          <div class=\"comparison-card wrong\">\n            <div class=\"comparison-badge\">\u274c Cloud-Centric (Violates ISRO PS)</div>\n            <div class=\"comparison-title\">Standard Agent Architecture (Comet, Browser Use, UFO)</div>\n            <div class=\"flow-pipeline-visual\">\n              <div class=\"flow-step-line\">\n                <span class=\"node-box neutral\">Raw Screen</span>\n                <span>\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u25ba</span>\n                <span class=\"node-box red\">Cloud Server VLM</span>\n              </div>\n              <div style=\"color:#DC2626; font-size:11px; margin: 4px 0 8px 10px;\">\n                \u26a0\ufe0f Raw Aadhaar, PAN, &amp; Faces cross public internet unredacted!\n              </div>\n              <div class=\"flow-step-line\">\n                <span class=\"node-box red\">Cloud VLM</span>\n                <span>\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u25ba</span>\n                <span class=\"node-box neutral\">Browser (Click/Type)</span>\n              </div>\n            </div>\n            <div class=\"comparison-desc\">\n              Server receives high-resolution unredacted screenshots. A security breach at the cloud provider exposes classified ISRO telemetry, vendor bank accounts, and citizen PII under the DPDP Act 2023.\n            </div>\n          </div>\n\n          <div class=\"comparison-card correct\">\n            <div class=\"comparison-badge\">\u2705 PRATYAKSHA (100% PS Compliant)</div>\n            <div class=\"comparison-title\">Sovereign On-Device Sanitization Shield</div>\n            <div class=\"flow-pipeline-visual\">\n              <div class=\"flow-step-line\">\n                <span class=\"node-box neutral\">Raw Screen</span>\n                <span>\u2500\u2500\u25ba</span>\n                <span class=\"node-box green\">WebGPU ML Shield</span>\n              </div>\n              <div style=\"color:#059669; font-size:11px; margin: 4px 0 8px 10px;\">\n                \ud83d\udd12 Zero raw PII leaves device. Only tokens like \u27e8AADHAAR_01\u27e9!\n              </div>\n              <div class=\"flow-step-line\">\n                <span class=\"node-box green\">Clean Canvas</span>\n                <span>\u2500\u2500\u25ba</span>\n                <span class=\"node-box amber\">Server VLM (Plans)</span>\n                <span>\u2500\u2500\u25ba</span>\n                <span class=\"node-box green\">Local Vault (Fills)</span>\n              </div>\n            </div>\n            <div class=\"comparison-desc\">\n              All pixel detection, OCR, and pseudonymization run 100% locally in browser memory. The server only sees anonymous placeholder tokens and returns abstract action plans.\n            </div>\n          </div>\n        </div>\n\n        <div class=\"callout info\">\n          <div class=\"callout-icon\">\ud83d\udef0</div>\n          <div class=\"callout-body\">\n            <strong>Why ISRO Urgently Needs This:</strong>\n            ISRO scientists and staff operate internal browser-based portals: e-Office file management, GeM procurement tenders, ground-station telemetry consoles, and HR/personnel portals. All are legally bound by the National Information Security Policy Guidelines (NISPG) and the Digital Personal Data Protection (DPDP) Act 2023. A generic cloud agent screenshotting these screens is a major security breach.\n          </div>\n        </div>",
  "rubric": "<div class=\"section-header\">\n          <div class=\"section-icon-badge\">\u2696</div>\n          <h2 class=\"section-title\">Evaluation Rubric \u2014 Decoded for Victory</h2>\n        </div>\n        <p class=\"section-lead\">\n          Understanding the grading weights reveals where the real competition will be won or lost. ISRO is evaluating defense-grade privacy rigor above all else.\n        </p>\n\n        <div class=\"rubric-container\">\n          <div class=\"rubric-grid\">\n            <div class=\"rubric-card high\">\n              <div class=\"rubric-pct\">20%</div>\n              <div class=\"rubric-label\">PII Detection</div>\n              <div class=\"rubric-sub\">Recall &amp; Precision</div>\n            </div>\n            <div class=\"rubric-card high\">\n              <div class=\"rubric-pct\">20%</div>\n              <div class=\"rubric-label\">Redaction Precision</div>\n              <div class=\"rubric-sub\">IoU Tight Bounding Box</div>\n            </div>\n            <div class=\"rubric-card mid\">\n              <div class=\"rubric-pct\">25%</div>\n              <div class=\"rubric-label\">Visual Context</div>\n              <div class=\"rubric-sub\">Scene Understanding</div>\n            </div>\n            <div class=\"rubric-card mid\">\n              <div class=\"rubric-pct\">20%</div>\n              <div class=\"rubric-label\">Client Resources</div>\n              <div class=\"rubric-sub\">RAM, VRAM, CPU &lt;8%</div>\n            </div>\n            <div class=\"rubric-card low\">\n              <div class=\"rubric-pct\">15%</div>\n              <div class=\"rubric-label\">End-to-End Latency</div>\n              <div class=\"rubric-sub\">Loop Cycle Time</div>\n            </div>\n          </div>\n\n          <div class=\"rubric-banner\">\n            <div class=\"rubric-banner-icon\">\ud83c\udfaf</div>\n            <div class=\"rubric-banner-text\">\n              <strong>Strategic Reality:</strong> Combined Privacy Marks = <strong>40%</strong>. Client Resource Efficiency = <strong>20%</strong>. That means <strong>60% of total marks are awarded before the agent takes a single action in the browser!</strong> Teams that build a complex agent with sloppy privacy will lose to PRATYAKSHA's mathematically provable sanitization pipeline.\n            </div>\n          </div>\n        </div>",
  "market": "<div class=\"section-header\">\n          <div class=\"section-icon-badge\">\ud83d\udd0d</div>\n          <h2 class=\"section-title\">Market Analysis \u2014 Why Every Existing Solution Fails</h2>\n        </div>\n        <p class=\"section-lead\">\n          Every existing commercial agent and redaction toolkit fails the ISRO problem statement in one of two catastrophic ways:\n          <strong>(A)</strong> It transmits raw, unredacted pixels to an external cloud model, or \n          <strong>(B)</strong> It relies on cloud-based APIs for redaction, meaning sensitive data crosses the network wire before it is protected.\n        </p>\n\n        <h3 style=\"font-family:'Outfit',sans-serif; font-size:18px; margin: 24px 0 12px; color:var(--text-main);\">\n          A. Commercial &amp; Open-Source Browser Agents\n        </h3>\n        <div class=\"table-container\">\n          <table>\n            <thead>\n              <tr>\n                <th>Agent Product</th>\n                <th>Architecture Flow</th>\n                <th>PS Compliance</th>\n                <th>Fatal Flaw Under PS-26171</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td class=\"strong-col\">Perplexity Comet</td>\n                <td>Raw screenshot \u2192 GPT-4o Cloud \u2192 Actions</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Transmits unredacted screen frames to external cloud servers</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Browser Use (Python)</td>\n                <td>Playwright DOM + raw screenshot \u2192 Cloud LLM</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Full DOM and screen pixels egress directly across network</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Multion</td>\n                <td>Browser extension \u2192 Cloud VLM \u2192 Synthetic clicks</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Zero local privacy filtering; raw user session hosted on remote cloud</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Microsoft UFO Agent</td>\n                <td>Full desktop screenshot \u2192 Azure GPT-4V</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Sends unmasked OS &amp; browser pixels to cloud endpoints</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Google Project Mariner</td>\n                <td>Extension feed \u2192 Gemini 1.5 Flash Cloud</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Cloud-dependent visual processing; unredacted visual context egresses</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">WebVoyager / SeeAct</td>\n                <td>Raw image patches \u2192 GPT-4V</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Academic pipelines with zero on-device sanitization layer</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Adept ACT-1</td>\n                <td>Proprietary cloud model viewing raw frames</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Cloud-hosted foundation model; no on-device privacy guarantee</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n\n        <h3 style=\"font-family:'Outfit',sans-serif; font-size:18px; margin: 28px 0 12px; color:var(--text-main);\">\n          B. Existing PII Redaction Tools\n        </h3>\n        <div class=\"table-container\">\n          <table>\n            <thead>\n              <tr>\n                <th>Tool / Library</th>\n                <th>Modality</th>\n                <th>PS Compliance</th>\n                <th>Fatal Flaw Under PS-26171</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td class=\"strong-col\">Microsoft Presidio</td>\n                <td>Text-only NLP, Server-side Python</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Cannot detect text inside images/PDFs/canvas; requires heavy Python runtime</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Amazon Comprehend</td>\n                <td>Cloud REST API for text PII</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Requires sending raw text to AWS servers first \u2014 direct violation</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Google Cloud DLP</td>\n                <td>Cloud Data Loss Prevention API</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Raw data leaves client to be analyzed on Google Cloud</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">AWS Rekognition</td>\n                <td>Cloud CV for face detection</td>\n                <td><span class=\"badge fail\">FAILS</span></td>\n                <td>Raw image frames must be uploaded to AWS cloud servers</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Private AI SDK</td>\n                <td>On-prem containerized NLP</td>\n                <td><span class=\"badge partial\">PARTIAL</span></td>\n                <td>Server-side; no native in-browser WebGPU execution; lacks Indian PII algorithms</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n\n        <div class=\"callout success\">\n          <div class=\"callout-icon\">\ud83c\udfc6</div>\n          <div class=\"callout-body\">\n            <strong>The Massive Market White Space:</strong>\n            No product in the world combines: <strong>(1)</strong> In-browser lightweight execution, <strong>(2)</strong> Computer vision for non-DOM pixels (PDFs, canvas, scans), <strong>(3)</strong> Algorithmic Indian PII verification (Verhoeff, PAN, GSTIN), and <strong>(4)</strong> Autonomous browser agent execution with reversible token rehydration. This is our undeniable competitive moat.\n          </div>\n        </div>",
  "architecture": "<div class=\"section-header\">\n          <div class=\"section-icon-badge\">\ud83c\udfd7</div>\n          <h2 class=\"section-title\">Full System Architecture</h2>\n        </div>\n        <p class=\"section-lead\">\n          PRATYAKSHA operates as a Manifest V3 browser extension with an Offscreen Worker running quantized ONNX models over WebGPU, communicating with an isolated intranet-hosted VLM.\n        </p>\n\n        <!-- \u2500\u2500 INTERACTIVE MERMAID ARCHITECTURE CANVAS \u2500\u2500 -->\n        <div class=\"mermaid-wrapper\" id=\"masterPlanArchWrap\">\n          <div class=\"mermaid-header\">\n            <div class=\"mermaid-title\">\n              <span>\ud83c\udfdb\ufe0f End-to-End System Topology &amp; Privacy Boundary Flow</span>\n            </div>\n            <div class=\"mermaid-controls\">\n              <button class=\"mermaid-btn\" id=\"mpZoomInBtn\" title=\"Zoom In\">\ud83d\udd0d +</button>\n              <button class=\"mermaid-btn\" id=\"mpZoomOutBtn\" title=\"Zoom Out\">\ud83d\udd0d &minus;</button>\n              <button class=\"mermaid-btn\" id=\"mpZoomResetBtn\" title=\"Reset View\">&#x23FA; Reset</button>\n            </div>\n            <div class=\"mermaid-meta\">\n              <span class=\"mermaid-tag mt-orange\">Zero-Raw-PII Wire</span>\n              <span class=\"mermaid-tag mt-purple\">Local Ephemeral Vault</span>\n              <span class=\"mermaid-tag mt-green\">WebGPU &lt;120ms</span>\n            </div>\n          </div>\n\n          <div class=\"mermaid-legend\">\n            <div class=\"legend-item\"><span class=\"legend-dot ld-client\"></span> Browser Sandbox (MV3)</div>\n            <div class=\"legend-item\"><span class=\"legend-dot ld-shield\"></span> WebGPU Privacy Shield</div>\n            <div class=\"legend-item\"><span class=\"legend-dot ld-vault\"></span> Reversible Vault</div>\n            <div class=\"legend-item\"><span class=\"legend-dot ld-gateway\"></span> Security Gateway</div>\n            <div class=\"legend-item\"><span class=\"legend-dot ld-cloud\"></span> Sovereign VLM Intranet</div>\n          </div>\n\n          <div class=\"mermaid-box\" id=\"masterPlanMermaidBox\">\n            <pre class=\"mermaid\" id=\"mpMermaidPre\">\nflowchart TD\n    classDef client fill:#EFF6FF,stroke:#2563EB,stroke-width:2px,color:#1E40AF;\n    classDef shield fill:#FFF7ED,stroke:#EA580C,stroke-width:2px,color:#9A3412;\n    classDef vault fill:#F5F3FF,stroke:#7C3AED,stroke-width:2px,color:#5B21B6;\n    classDef gateway fill:#FEF3C7,stroke:#D97706,stroke-width:2px,color:#92400E;\n    classDef cloud fill:#ECFDF5,stroke:#059669,stroke-width:2px,color:#065F46;\n\n    subgraph MV3 [\"\ud83d\udd12 CLIENT BROWSER EXTENSION (Chrome MV3 On-Device Sandbox)\"]\n        direction TB\n        User([\"\ud83d\udc64 User / Security Operator\"]):::client\n        SidePanel[\"\ud83d\udda5\ufe0f Side Panel UI (Audit HUD \u00b7 Approval Gate)\"]:::client\n        TargetTab[\"\ud83c\udf10 Active Web Tab (ISRO e-Procurement / Portal)\"]:::client\n        ContentScript[\"\ud83d\udcdc Content Script (DOM Tree Walker & Synthesizer)\"]:::client\n        \n        subgraph PRIVACY_SHIELD [\"\u26a1 WebGPU Privacy Shield (Offscreen Document)\"]\n            FrameDiff[\"\u26a1 8x8 Tile Diff (Skips 85% Static Frames)\"]:::shield\n            Detector[\"\ud83c\udfaf Multi-Model Detector (DBNet + Face + CRNN)\"]:::shield\n            Redactor[\"\ud83d\udee1\ufe0f Inpainting Redactor (4px Safety Dilation)\"]:::shield\n        end\n\n        subgraph LOCAL_VAULT [\"\ud83d\udd10 In-Memory Vault Service (Ephemeral)\"]\n            TokenGen[\"\ud83c\udfb2 Deterministic Session Tokenizer\"]:::vault\n            AESVault[\"\ud83d\uddc4\ufe0f AES-256-GCM RAM Vault\"]:::vault\n            Rehydration[\"\ud83d\udd04 Rehydration Engine (Token -> Real Value)\"]:::vault\n        end\n    end\n\n    subgraph WIRE_INGRESS [\"\ud83d\udee1\ufe0f ISRO INTRANET SECURE INGRESS\"]\n        direction TB\n        APIGateway[\"\ud83d\udeaa mTLS API Gateway (Strict Zero-Raw-PII Inspector)\"]:::gateway\n        AuditQueue[\"\ud83d\udccb Cryptographic Action Ledger (WORM Log)\"]:::gateway\n    end\n\n    subgraph CLOUD_CORE [\"\u2601\ufe0f AIR-GAPPED REASONING CLUSTER\"]\n        direction TB\n        Orchestrator[\"\ud83e\udde0 LangGraph Dual-Track Agent Orchestrator\"]:::cloud\n        VLM[\"\ud83e\udd16 Sovereign Qwen2.5-VL Reasoning Engine\"]:::cloud\n        SafetyVerifier[\"\u2696\ufe0f Policy & Deterministic Constraint Checker\"]:::cloud\n    end\n\n    User -->|\"1. Submit Task Intent\"| SidePanel\n    SidePanel -->|\"2. Initiate Perception Loop\"| ContentScript\n    ContentScript -->|\"3. DOM Extraction + Capture Viewport\"| TargetTab\n    TargetTab -->|\"4. Raw Pixels + DOM Node Hierarchy\"| FrameDiff\n    FrameDiff -->|\"5. Dirty Tiles Only\"| Detector\n    Detector -->|\"6. Detected PII Bounds & Text\"| TokenGen\n    TokenGen -->|\"7. Cache Real PII (RAM Only)\"| AESVault\n    TokenGen -->|\"8. Token Replacement Map\"| Redactor\n    Redactor -->|\"9. Sanitized Image + Anonymized JSON Tree\"| APIGateway\n\n    APIGateway -->|\"10. Forward Anonymized Prompt & Image\"| Orchestrator\n    Orchestrator -->|\"11. Visual Reasoner Prompt\"| VLM\n    VLM -->|\"12. Structured Action Plan with Tokens\"| SafetyVerifier\n    SafetyVerifier -->|\"13. Validated Action Stream\"| APIGateway\n    APIGateway -->|\"14. Real-Time Action Stream\"| SidePanel\n\n    SidePanel -->|\"15. Request User Approval if High Risk\"| User\n    SidePanel -->|\"16. Authorized Action Frame\"| Rehydration\n    Rehydration -->|\"17. Decrypt Real Value Locally\"| AESVault\n    Rehydration -->|\"18. Dispatch Native Event to DOM\"| ContentScript\n    ContentScript -->|\"19. Synthesize Click / Input\"| TargetTab\n    ContentScript -.->|\"20. Closed-Loop Next Frame Verification\"| FrameDiff\n            </pre>\n            <div class=\"mermaid-canvas-hint\">\n              <span>\ud83d\udd90\ufe0f Drag to Pan</span>\n              <span>\u00b7</span>\n              <span>\ud83d\udd0d Pinch or Scroll to Zoom</span>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"arch-schematic\">\n          <div class=\"arch-block\">\n            <div class=\"arch-block-header\">\n              <div class=\"arch-block-title\">\n                <span>\ud83d\udee1 Client-Side Browser Extension (Chrome MV3 / Firefox WebExtension)</span>\n              </div>\n              <span class=\"badge pass\">Runs 100% On-Device</span>\n            </div>\n\n            <div class=\"arch-grid-components\">\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83d\udcc4 Content Script</div>\n                <div class=\"subcomp-tech\">content.js \u00b7 Tab Context</div>\n                <div class=\"subcomp-desc\">\n                  DOM tree extraction, MutationObserver, dirty-tile change tracking, and synthetic event action dispatcher (clicks, typing).\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83e\udde0 Offscreen Worker</div>\n                <div class=\"subcomp-tech\">offscreen.js \u00b7 WebGPU Context</div>\n                <div class=\"subcomp-desc\">\n                  Loads ONNX Runtime Web. Executes Face Detection, DBNet Text Detection, Indic OCR, and Canvas Inpainting without freezing UI.\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\u2699\ufe0f Service Worker</div>\n                <div class=\"subcomp-tech\">background.js \u00b7 Central Hub</div>\n                <div class=\"subcomp-desc\">\n                  Maintains ephemeral Pseudonym Vault in memory, builds SHA-256 Egress Hash Chain, routes actions, and enforces security.\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83d\udcca Side Panel / HUD</div>\n                <div class=\"subcomp-tech\">sidepanel.html \u00b7 Audit View</div>\n                <div class=\"subcomp-desc\">\n                  Split-screen live diff HUD (Raw screen vs Sanitized wire payload), Egress Ledger verifier, and Paranoid Mode manual gates.\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83c\uddee\ud83c\uddf3 Sovereign Rule Engine</div>\n                <div class=\"subcomp-tech\">pii-rules.js \u00b7 Pure JS (0MB)</div>\n                <div class=\"subcomp-desc\">\n                  Verhoeff dihedral-group check (Aadhaar), PAN structural checks, GSTIN modulo-36, and IFSC RBI registry lookup.\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83d\udd10 Rehydration Vault</div>\n                <div class=\"subcomp-tech\">vault.js \u00b7 Ephemeral Memory</div>\n                <div class=\"subcomp-desc\">\n                  Maps <code>\u27e8AADHAAR_01\u27e9 \u2194 \"5432 1098 7654\"</code>. Rehydrates actions locally. Auto-purges after 3-minute session TTL.\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- NETWORK BOUNDARY VISUAL -->\n          <div class=\"wire-boundary\">\n            <span>\ud83d\udd12 ZERO-TRUST NETWORK BOUNDARY: ONLY SANITIZED PIXELS + PLACEHOLDER TOKENS CROSS</span>\n          </div>\n\n          <div class=\"arch-block\" style=\"background:#FFFFFF; border-color:#BFDBFE;\">\n            <div class=\"arch-block-header\">\n              <div class=\"arch-block-title\">\n                <span style=\"color:#1D4ED8;\">\ud83d\udda5 ISRO Intranet / On-Premise Server (Air-Gapped Compatible)</span>\n              </div>\n              <span class=\"badge info\">vLLM / Ollama Deployment</span>\n            </div>\n            <p style=\"font-size:13.5px; color:var(--text-body); margin-bottom:12px;\">\n              <strong>Qwen2.5-VL-7B-Instruct / InternVL2.5:</strong> Receives sanitized WebP image + abstract scene graph containing tokens like <code>\u27e8AADHAAR_01\u27e9</code>. Returns structured JSON action plan instructing the extension which node to interact with.\n            </p>\n            <div style=\"background:#F8F5EE; padding:12px; border-radius:8px; font-family:'JetBrains Mono',monospace; font-size:11.5px; color:#1C1917;\">\n              Response Payload: {\"thought\": \"Entering sanitized Aadhaar token into form\", \"actions\": [{\"type\":\"TYPE\", \"target\":\"#uid\", \"val\":\"\u27e8AADHAAR_01\u27e9\"}]}\n            </div>\n          </div>\n        </div>",
  "models": "<div class=\"section-header\">\n          <div class=\"section-icon-badge\">\ud83e\udde0</div>\n          <h2 class=\"section-title\">On-Device Model Pipeline \u2014 Why Not One Big VLM?</h2>\n        </div>\n\n        <div class=\"callout danger\">\n          <div class=\"callout-icon\">\u26a0\ufe0f</div>\n          <div class=\"callout-body\">\n            <strong>The Fatal Trap: Attempting to Run a Single Local VLM in Browser</strong><br/>\n            Some teams will try to load SmolVLM-256M (~500MB) or Moondream2 (~3.7GB) locally via WebAssembly and ask it to find PII. This causes 4\u20138 second inference latency, crashes browser memory with 1GB+ VRAM consumption, and hallucinates on structured ID numbers. It completely destroys the 20% Resource and 15% Latency rubric scores.\n          </div>\n        </div>\n\n        <div class=\"callout success\">\n          <div class=\"callout-icon\">\u2728</div>\n          <div class=\"callout-body\">\n            <strong>The Winning Architecture: Specialized Cascaded Micro-Models</strong><br/>\n            Instead of one slow, bloated generalist VLM, PRATYAKSHA uses a cascade of specialized, INT8-quantized ONNX models running on WebGPU. Each model solves one exact sub-problem with mathematical precision. Total footprint: <strong>~20 MB</strong>. Total latency: <strong>~48 ms</strong>.\n          </div>\n        </div>\n\n        <div class=\"model-deck\">\n          <div class=\"model-card\">\n            <div class=\"model-card-top\">\n              <div class=\"model-name\">Face Detector</div>\n              <div class=\"model-size-badge\">2.5 MB ONNX</div>\n              <div class=\"model-desc\">\n                Ultra-Light-Fast-Face-Detector. Detects human faces in uploaded ID photos, webcam KYC frames, and employee directory cards.\n              </div>\n            </div>\n            <div class=\"model-latency-tag\">\u26a1 ~12ms on WebGPU</div>\n          </div>\n\n          <div class=\"model-card\">\n            <div class=\"model-card-top\">\n              <div class=\"model-name\">Text Region Detector</div>\n              <div class=\"model-size-badge\">6.0 MB ONNX</div>\n              <div class=\"model-desc\">\n                DBNet-Tiny. Rapidly generates bounding polygons for all text in canvas, PDF viewer embeds, scans, and classified document letterheads.\n              </div>\n            </div>\n            <div class=\"model-latency-tag\">\u26a1 ~20ms on WebGPU</div>\n          </div>\n\n          <div class=\"model-card\">\n            <div class=\"model-card-top\">\n              <div class=\"model-name\">Indic OCR Engine</div>\n              <div class=\"model-size-badge\">8.0 MB ONNX</div>\n              <div class=\"model-desc\">\n                CRNN fine-tuned on IIIT-ILST Devanagari + synthetic Indian ID corpus. Transcribes English and Hindi characters with official stamp recognition.\n              </div>\n            </div>\n            <div class=\"model-latency-tag\">\u26a1 ~15ms per region</div>\n          </div>\n\n          <div class=\"model-card\">\n            <div class=\"model-card-top\">\n              <div class=\"model-name\">UI Region Classifier</div>\n              <div class=\"model-size-badge\">4.0 MB ONNX</div>\n              <div class=\"model-desc\">\n                MobileNetV4-Tiny. Classifies tiles into sensitivity tiers: password field, document scan preview, video feed, or safe navigation bar.\n              </div>\n            </div>\n            <div class=\"model-latency-tag\">\u26a1 ~10ms on WebGPU</div>\n          </div>\n\n          <div class=\"model-card\">\n            <div class=\"model-card-top\">\n              <div class=\"model-name\">Indian PII Rule Engine</div>\n              <div class=\"model-size-badge\">0.0 MB (Pure JS)</div>\n              <div class=\"model-desc\">\n                Verhoeff dihedral algorithm, PAN regex + structural type check, GSTIN modulo-36, IFSC database lookup. Algorithmic zero false positives.\n              </div>\n            </div>\n            <div class=\"model-latency-tag\">\u26a1 &lt;1ms execution</div>\n          </div>\n        </div>\n\n        <!-- STATS BAR -->\n        <div class=\"stats-bar\">\n          <div class=\"stat-item green\">\n            <div class=\"stat-label\">Total Model Footprint</div>\n            <div class=\"stat-value\">~20 MB</div>\n          </div>\n          <div class=\"stat-item blue\">\n            <div class=\"stat-label\">Runtime WebGPU VRAM</div>\n            <div class=\"stat-value\">&lt;85 MB</div>\n          </div>\n          <div class=\"stat-item orange\">\n            <div class=\"stat-label\">Total Sanitization Time</div>\n            <div class=\"stat-value\">~48 ms</div>\n          </div>\n          <div class=\"stat-item purple\">\n            <div class=\"stat-label\">Background Idle CPU</div>\n            <div class=\"stat-value\">&lt;8%</div>\n          </div>\n        </div>",
  "innovations": "<div class=\"section-header\">\n          <div class=\"section-icon-badge\">\u2728</div>\n          <h2 class=\"section-title\">6 Core Innovations &amp; Competitive Moats</h2>\n        </div>\n\n        <div class=\"innovation-grid\">\n          <div class=\"inno-card\">\n            <div class=\"inno-top\">\n              <div class=\"inno-badge-num\">INNOVATION 01</div>\n              <h3>Reversible Pseudonymization Vault</h3>\n              <p>\n                Instead of destructive black-box pixel masking (which destroys context and causes VLM hallucination), detected PII is replaced with deterministic typed tokens like <code>\u27e8AADHAAR_01\u27e9</code>. The real value is kept in ephemeral client memory. The server plans using tokens; the client rehydrates locally before typing into the form.\n              </p>\n            </div>\n            <div class=\"inno-tag\">Target: 25% Context + 20% Redaction Rubric</div>\n          </div>\n\n          <div class=\"inno-card\">\n            <div class=\"inno-top\">\n              <div class=\"inno-badge-num\">INNOVATION 02</div>\n              <h3>Fail-Closed Dual-Channel Fusion</h3>\n              <p>\n                Merges the Fast DOM Channel (2ms, catches input tags and ARIA labels) with the Deep Vision Channel (45ms, catches PDFs, images, and canvas pixels). If <em>either</em> channel flags a region as sensitive, it is strictly masked. Pages with \"SECRET\" headers auto-escalate to paranoid mode.\n              </p>\n            </div>\n            <div class=\"inno-tag\">Target: 20% PII Recall (&gt;99% Recall)</div>\n          </div>\n\n          <div class=\"inno-card\">\n            <div class=\"inno-top\">\n              <div class=\"inno-badge-num\">INNOVATION 03</div>\n              <h3>Indian Sovereign PII Stack</h3>\n              <p>\n                Verhoeff dihedral checksum eliminates false positives on 12-digit telemetry codes. PAN 4th-character validation ensures entity matching. GSTIN modulo-36 checks, RBI IFSC registry lookup, and Devanagari keyword regex (\u0906\u0927\u093e\u0930, \u0917\u094b\u092a\u0928\u0940\u092f, \u092a\u0948\u0928). Built for India, not ported to India.\n              </p>\n            </div>\n            <div class=\"inno-tag\">Target: 20% PII Precision (&gt;98% Precision)</div>\n          </div>\n\n          <div class=\"inno-card\">\n            <div class=\"inno-top\">\n              <div class=\"inno-badge-num\">INNOVATION 04</div>\n              <h3>Cryptographic Egress Audit Ledger</h3>\n              <p>\n                Every outbound payload packet is cryptographically hashed in a SHA-256 Merkle chain. The Side Panel provides a live split-screen visual diff: Raw Screen on the left, Sanitized Wire Payload on the right. Judges can verify byte-for-byte that zero raw PII escaped the machine.\n              </p>\n            </div>\n            <div class=\"inno-tag\">Target: Verifiability &amp; Stage WOW Factor</div>\n          </div>\n\n          <div class=\"inno-card\">\n            <div class=\"inno-top\">\n              <div class=\"inno-badge-num\">INNOVATION 05</div>\n              <h3>Cascaded 8\u00d78 Dirty-Tile Compute</h3>\n              <p>\n                The 1280\u00d7800 viewport is split into 64 tiles (each ~160\u00d7100px). A 64-bit perceptual dHash tracks pixel deltas. Unchanged browser tabs, navigation bars, and static headers are cached indefinitely. Only mutated tiles trigger model inference \u2014 reducing compute burden by 84%.\n              </p>\n            </div>\n            <div class=\"inno-tag\">Target: 20% Client Resource Utilization</div>\n          </div>\n\n          <div class=\"inno-card\">\n            <div class=\"inno-top\">\n              <div class=\"inno-badge-num\">INNOVATION 06</div>\n              <h3>Prompt Injection Hardening &amp; Safety Gate</h3>\n              <p>\n                All web page content is encapsulated inside <code>&lt;untrusted_page_context&gt;</code> XML delimiters. Strict domain allowlists prevent malicious redirection. Destructive actions (SUBMIT, DELETE, APPROVE) enforce a mandatory human approval modal before execution.\n              </p>\n            </div>\n            <div class=\"inno-tag\">Target: Enterprise Defense Credibility</div>\n          </div>\n        </div>",
  "metrics": "<div class=\"section-header\">\n          <div class=\"section-icon-badge\">\ud83d\udcca</div>\n          <h2 class=\"section-title\">Target Benchmark Metrics vs Baseline</h2>\n        </div>\n        <p class=\"section-lead\">\n          To prove empirical superiority to the ISRO jury, we construct <strong>IndoGov-PII Bench</strong>: a 250-screen dataset of synthetic Indian government portals with ground-truth bounding boxes, evaluating accuracy, resource load, and latency.\n        </p>\n\n        <div class=\"table-container\">\n          <table>\n            <thead>\n              <tr>\n                <th>Rubric Category</th>\n                <th>Metric</th>\n                <th>Baseline (Presidio + EasyOCR)</th>\n                <th>PRATYAKSHA Target</th>\n                <th>Technical Advantage</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td class=\"strong-col\">PII Detection (20%)</td>\n                <td>Precision</td>\n                <td><span class=\"badge fail\">78.4%</span></td>\n                <td><span class=\"badge pass\">98.7%</span></td>\n                <td>Verhoeff algorithm eliminates false alerts on 12-digit serials</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">PII Detection (20%)</td>\n                <td>Recall</td>\n                <td><span class=\"badge fail\">84.1%</span></td>\n                <td><span class=\"badge pass\">99.4%</span></td>\n                <td>Fail-closed fusion catches both DOM and canvas-rendered pixels</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Redaction Precision (20%)</td>\n                <td>Mask IoU</td>\n                <td><span class=\"badge fail\">0.62</span></td>\n                <td><span class=\"badge pass\">0.93</span></td>\n                <td>4px dilation halo; clean semantic token inpainting preserves layout</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Visual Context (25%)</td>\n                <td>Task Success Rate</td>\n                <td><span class=\"badge fail\">42.0%</span></td>\n                <td><span class=\"badge pass\">94.5%</span></td>\n                <td>Placeholder tokens maintain syntactic structure for the VLM</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Client Resource (20%)</td>\n                <td>Client RAM</td>\n                <td><span class=\"badge fail\">680 MB</span></td>\n                <td><span class=\"badge pass\">&lt;110 MB</span></td>\n                <td>Browser-native ONNX WebGPU worker; zero Python dependency</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Client Resource (20%)</td>\n                <td>VRAM Usage</td>\n                <td><span class=\"badge fail\">1.2 GB</span></td>\n                <td><span class=\"badge pass\">&lt;85 MB</span></td>\n                <td>INT8 quantized MobileNet backbones executed over WebGPU</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Client Resource (20%)</td>\n                <td>Idle CPU Load</td>\n                <td><span class=\"badge fail\">45%</span></td>\n                <td><span class=\"badge pass\">&lt;8%</span></td>\n                <td>Perceptual dHash dirty-tile caching avoids continuous inference</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Latency (15%)</td>\n                <td>Sanitization Latency</td>\n                <td><span class=\"badge fail\">380 ms</span></td>\n                <td><span class=\"badge pass\">48 ms</span></td>\n                <td>Parallel WebGPU pipeline dispatch across detection stages</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Latency (15%)</td>\n                <td>End-to-End Loop</td>\n                <td><span class=\"badge fail\">3.2 s</span></td>\n                <td><span class=\"badge pass\">1.1 s</span></td>\n                <td>Sub-second perception-action loop with local intranet VLM</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>",
  "sprint": "<div class=\"section-header\">\n          <div class=\"section-icon-badge\">\ud83d\uddd3</div>\n          <h2 class=\"section-title\">4-Phase Sprint Plan &amp; Team Distribution</h2>\n        </div>\n\n        <div class=\"sprint-grid\">\n          <div class=\"sprint-card\">\n            <div class=\"sprint-phase-num\">Phase 1 \u00b7 Days 1\u20133</div>\n            <div class=\"sprint-title\">Foundation &amp; Scaffolding</div>\n            <ul>\n              <li>Manifest V3 extension scaffold with Offscreen Worker</li>\n              <li>Pure JS Indian PII rule engine (Verhoeff, PAN, GSTIN)</li>\n              <li>DOM extractor + MutationObserver pipeline</li>\n              <li>Mock ISRO e-Office &amp; GeM portal test suite</li>\n            </ul>\n          </div>\n\n          <div class=\"sprint-card\">\n            <div class=\"sprint-phase-num\">Phase 2 \u00b7 Days 4\u20137</div>\n            <div class=\"sprint-title\">Edge ML &amp; WebGPU Pipeline</div>\n            <ul>\n              <li>Export INT8 ONNX models (Face, DBNet-Tiny, Indic CRNN)</li>\n              <li>Implement WebGPU inference in ONNX Runtime Web</li>\n              <li>8\u00d78 dirty-tile perceptual hash filter</li>\n              <li>Fail-closed spatial IoU fusion algorithm</li>\n            </ul>\n          </div>\n\n          <div class=\"sprint-card\">\n            <div class=\"sprint-phase-num\">Phase 3 \u00b7 Days 8\u201311</div>\n            <div class=\"sprint-title\">Vault, Ledger &amp; Agent Loop</div>\n            <ul>\n              <li>In-memory reversible pseudonymization vault</li>\n              <li>Cryptographic SHA-256 egress ledger &amp; split-screen HUD</li>\n              <li>Qwen2.5-VL server setup + wire JSON protocol</li>\n              <li>Action executor with human confirmation gates</li>\n            </ul>\n          </div>\n\n          <div class=\"sprint-card\">\n            <div class=\"sprint-phase-num\">Phase 4 \u00b7 Days 12\u201314</div>\n            <div class=\"sprint-title\">Benchmarking &amp; Stage Demo</div>\n            <ul>\n              <li>IndoGov-PII Bench 250-screen evaluation dataset</li>\n              <li>Automated metric harness (IoU, Precision, Recall, Latency)</li>\n              <li>Prompt injection defense &amp; domain allowlist verification</li>\n              <li>Full rehearsal of live ISRO procurement portal demo</li>\n            </ul>\n          </div>\n        </div>\n\n        <h3 style=\"font-family:'Outfit',sans-serif; font-size:18px; margin: 28px 0 14px; color:var(--text-main);\">\n          Team Role Matrix (5-Member Squad)\n        </h3>\n        <div class=\"table-container\">\n          <table>\n            <thead>\n              <tr>\n                <th>Member</th>\n                <th>Core Track</th>\n                <th>Key Deliverables</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td class=\"strong-col\">Member 1</td>\n                <td>Extension &amp; UI Lead</td>\n                <td>Chrome/Firefox MV3 extension, content scripts, synthetic action dispatcher, audit HUD overlay</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Member 2</td>\n                <td>Edge ML &amp; WebGPU Lead</td>\n                <td>ONNX Runtime Web pipeline, INT8 quantization, WebGPU worker, 8\u00d78 dirty-tile optimizer</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Member 3</td>\n                <td>PII &amp; Security Lead</td>\n                <td>Verhoeff/PAN/GSTIN rule engines, in-memory vault, SHA-256 egress ledger, injection defense</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Member 4</td>\n                <td>Server &amp; VLM Lead</td>\n                <td>Qwen2.5-VL-7B server deployment (vLLM), wire protocol handler, air-gapped demo infrastructure</td>\n              </tr>\n              <tr>\n                <td class=\"strong-col\">Member 5</td>\n                <td>Benchmark &amp; Demo Lead</td>\n                <td>IndoGov-PII Bench 250-screen ground truth, metric evaluation harness, mock e-Office portal</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n\n        <div class=\"callout info\" style=\"margin-top:24px;\">\n          <div class=\"callout-icon\">\ud83d\udcac</div>\n          <div class=\"callout-body\">\n            <strong>The Winning Pitch to the Judges:</strong><br/>\n            <em>\"Competitors send your screen to an external cloud and ask you to trust them. PRATYAKSHA creates a sovereign on-device sanitization shield right inside the browser. We keep real sensitive data in an ephemeral local vault, transmit only anonymous placeholder tokens that your internal VLM can plan over, and provide a cryptographic receipt for every single byte that crosses the wire.\"</em>\n          </div>\n        </div>",
  "architecture_part1": "<div class=\"section-header\">\n          <div class=\"section-icon-badge\">\ud83c\udfd7</div>\n          <h2 class=\"section-title\">Full System Architecture</h2>\n        </div>\n        <p class=\"section-lead\">\n          PRATYAKSHA operates as a Manifest V3 browser extension with an Offscreen Worker running quantized ONNX models over WebGPU, communicating with an isolated intranet-hosted VLM.\n        </p>\n\n        <!-- \u2500\u2500 INTERACTIVE MERMAID ARCHITECTURE CANVAS \u2500\u2500 -->\n        <div class=\"mermaid-wrapper\" id=\"masterPlanArchWrap\">\n          <div class=\"mermaid-header\">\n            <div class=\"mermaid-title\">\n              <span>\ud83c\udfdb\ufe0f End-to-End System Topology &amp; Privacy Boundary Flow</span>\n            </div>\n            <div class=\"mermaid-controls\">\n              <button class=\"mermaid-btn\" id=\"mpZoomInBtn\" title=\"Zoom In\">\ud83d\udd0d +</button>\n              <button class=\"mermaid-btn\" id=\"mpZoomOutBtn\" title=\"Zoom Out\">\ud83d\udd0d &minus;</button>\n              <button class=\"mermaid-btn\" id=\"mpZoomResetBtn\" title=\"Reset View\">&#x23FA; Reset</button>\n            </div>\n            <div class=\"mermaid-meta\">\n              <span class=\"mermaid-tag mt-orange\">Zero-Raw-PII Wire</span>\n              <span class=\"mermaid-tag mt-purple\">Local Ephemeral Vault</span>\n              <span class=\"mermaid-tag mt-green\">WebGPU &lt;120ms</span>\n            </div>\n          </div>\n\n          <div class=\"mermaid-legend\">\n            <div class=\"legend-item\"><span class=\"legend-dot ld-client\"></span> Browser Sandbox (MV3)</div>\n            <div class=\"legend-item\"><span class=\"legend-dot ld-shield\"></span> WebGPU Privacy Shield</div>\n            <div class=\"legend-item\"><span class=\"legend-dot ld-vault\"></span> Reversible Vault</div>\n            <div class=\"legend-item\"><span class=\"legend-dot ld-gateway\"></span> Security Gateway</div>\n            <div class=\"legend-item\"><span class=\"legend-dot ld-cloud\"></span> Sovereign VLM Intranet</div>\n          </div>",
  "architecture_part2": "</div>\n\n        <div class=\"arch-schematic\">\n          <div class=\"arch-block\">\n            <div class=\"arch-block-header\">\n              <div class=\"arch-block-title\">\n                <span>\ud83d\udee1 Client-Side Browser Extension (Chrome MV3 / Firefox WebExtension)</span>\n              </div>\n              <span class=\"badge pass\">Runs 100% On-Device</span>\n            </div>\n\n            <div class=\"arch-grid-components\">\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83d\udcc4 Content Script</div>\n                <div class=\"subcomp-tech\">content.js \u00b7 Tab Context</div>\n                <div class=\"subcomp-desc\">\n                  DOM tree extraction, MutationObserver, dirty-tile change tracking, and synthetic event action dispatcher (clicks, typing).\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83e\udde0 Offscreen Worker</div>\n                <div class=\"subcomp-tech\">offscreen.js \u00b7 WebGPU Context</div>\n                <div class=\"subcomp-desc\">\n                  Loads ONNX Runtime Web. Executes Face Detection, DBNet Text Detection, Indic OCR, and Canvas Inpainting without freezing UI.\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\u2699\ufe0f Service Worker</div>\n                <div class=\"subcomp-tech\">background.js \u00b7 Central Hub</div>\n                <div class=\"subcomp-desc\">\n                  Maintains ephemeral Pseudonym Vault in memory, builds SHA-256 Egress Hash Chain, routes actions, and enforces security.\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83d\udcca Side Panel / HUD</div>\n                <div class=\"subcomp-tech\">sidepanel.html \u00b7 Audit View</div>\n                <div class=\"subcomp-desc\">\n                  Split-screen live diff HUD (Raw screen vs Sanitized wire payload), Egress Ledger verifier, and Paranoid Mode manual gates.\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83c\uddee\ud83c\uddf3 Sovereign Rule Engine</div>\n                <div class=\"subcomp-tech\">pii-rules.js \u00b7 Pure JS (0MB)</div>\n                <div class=\"subcomp-desc\">\n                  Verhoeff dihedral-group check (Aadhaar), PAN structural checks, GSTIN modulo-36, and IFSC RBI registry lookup.\n                </div>\n              </div>\n\n              <div class=\"arch-subcomponent\">\n                <div class=\"subcomp-name\">\ud83d\udd10 Rehydration Vault</div>\n                <div class=\"subcomp-tech\">vault.js \u00b7 Ephemeral Memory</div>\n                <div class=\"subcomp-desc\">\n                  Maps <code>\u27e8AADHAAR_01\u27e9 \u2194 \"5432 1098 7654\"</code>. Rehydrates actions locally. Auto-purges after 3-minute session TTL.\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- NETWORK BOUNDARY VISUAL -->\n          <div class=\"wire-boundary\">\n            <span>\ud83d\udd12 ZERO-TRUST NETWORK BOUNDARY: ONLY SANITIZED PIXELS + PLACEHOLDER TOKENS CROSS</span>\n          </div>\n\n          <div class=\"arch-block\" style=\"background:#FFFFFF; border-color:#BFDBFE;\">\n            <div class=\"arch-block-header\">\n              <div class=\"arch-block-title\">\n                <span style=\"color:#1D4ED8;\">\ud83d\udda5 ISRO Intranet / On-Premise Server (Air-Gapped Compatible)</span>\n              </div>\n              <span class=\"badge info\">vLLM / Ollama Deployment</span>\n            </div>\n            <p style=\"font-size:13.5px; color:var(--text-body); margin-bottom:12px;\">\n              <strong>Qwen2.5-VL-7B-Instruct / InternVL2.5:</strong> Receives sanitized WebP image + abstract scene graph containing tokens like <code>\u27e8AADHAAR_01\u27e9</code>. Returns structured JSON action plan instructing the extension which node to interact with.\n            </p>\n            <div style=\"background:#F8F5EE; padding:12px; border-radius:8px; font-family:'JetBrains Mono',monospace; font-size:11.5px; color:#1C1917;\">\n              Response Payload: {\"thought\": \"Entering sanitized Aadhaar token into form\", \"actions\": [{\"type\":\"TYPE\", \"target\":\"#uid\", \"val\":\"\u27e8AADHAAR_01\u27e9\"}]}\n            </div>\n          </div>\n        </div>"
};
